from collections import defaultdict, deque

def read_ints():
    return list(map(int, input().split()))

# Read input
N, M = read_ints()
E = read_ints()
graph = defaultdict(list)
indegree = [0] * N

# Read dependencies
for _ in range(M):
    T1, T2 = read_ints()
    graph[T2].append(T1)  # Reverse the direction for topological sort
    indegree[T1] += 1

# Topological sort using Kahn's algorithm
def topological_sort(graph, indegree):
    queue = deque()
    for i in range(N):
        if indegree[i] == 0:
            queue.append(i)

    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)
    return order

# Get the topological order
order = topological_sort(graph, indegree)

# Count the number of coprocessor calls
coprocessor_calls = 0
visited = [False] * N

for task in order:
    if E[task] == 1 and not visited[task]:
        coprocessor_calls += 1
        for dependent in graph[task]:
            visited[dependent] = True

print(coprocessor_calls)
